const e="st-gregorios-toronto-solo-song",c=2020,t="Built from the church's 2020 Solo Song guidelines (older edition). The source prints no fees, deadline, registration steps, contacts or prizes; those sections stay empty. Ages are not printed, only school grades as of 1 Jan 2020.",o={Title:"Rules & Criteria",Subtitle:"Sunday School Annual Talent Competition - Solo Song",NoticeTitle:"Please Read Before Registering",Notice:"The competition is held at {{Venue}} on {{CompetitionDate}} ({{CompetitionTime}}). Older 2020 rules: check the current circular.",Notes:["Judging components: General Appearance 10, Song Presentation 10, Pitch and Rhythm 20, Overall Presentation 10; total 50 points."],Sections:[{Key:"eligibility",Title:"Eligibility",Items:["The Solo Song Competition is held for Groups 1 to 7 (Nursery and KG up to Grade 12).","Group is decided by public or private school grade as of {{GradeCutoffDate}}.","A participant can enter only the English or the Malayalam solo song competition, not both."]},{Key:"dates",Title:"Date and time",Items:["The competition is on {{CompetitionDate}}, after Holy Qurbana, at around {{CompetitionTime}}."]},{Key:"venue",Title:"Venue",Items:["The venue is {{Venue}}."]},{Key:"general",Title:"General rules",Items:["The competition is held in Malayalam and English, separately.","Only Christian songs of appreciable quality in Malayalam or English are allowed.","Song sheets with lyrics are permitted.","No karaoke, musical or audio support is permitted.","No costumes or song-theme articles may be used.","No mobile phones or electronic devices are permitted.","A participant does not have to introduce the song or its title. If one is presented, the time starts with it and it counts in the 3 minute limit.","Each participant is given a unique badge number.","Badges must be collected in person at the registration desk.","Any clarification must be asked before each competition starts."]},{Key:"conduct",Title:"Conduct",Items:["No one may leave or enter the competition arena while a participant is performing.","Causing any distraction while a participant performs is strictly not permitted.","No clapping or cheering after each participant. Clapping is allowed only after each group is complete.","No participant or parent may approach the judges for any reason during the competitions. Only organising members may do so, for clarifications."]},{Key:"judging",Title:"Judging",Items:["The decision of the judges is final and binding for all competitions."]}],Documents:[]},i=[],n=[],a=[{Title:"Solo Song",Source:"Solo Song Guidelines 2020",Sections:{About:null,TimeAndFormat:["Time limit is 3 minutes.","No warning is given when the time limit is exceeded.","Exceeding the time limit means FIVE points are deducted from the combined score of all the judges."],Rules:null,Allowed:null,NotAllowed:null,Judging:["General Appearance 10 points.","Song Presentation 10 points.","Pitch and Rhythm 20 points.","Overall Presentation 10 points.","Total 50 points."],Points:null,Notes:null},Markdown:`## Time and format
- Time limit is 3 minutes.
- No warning is given when the time limit is exceeded.
- Exceeding the time limit means FIVE points are deducted from the combined score of all the judges.

## Judging
- General Appearance 10 points.
- Song Presentation 10 points.
- Pitch and Rhythm 20 points.
- Overall Presentation 10 points.
- Total 50 points.`}],s=[],r=[{Key:"CompetitionDate",Kind:"date",Label:"Competition date",Value:"2020-02-16",Source:"Solo Song Guidelines 2020"},{Key:"CompetitionTime",Kind:"time",Label:"Start time",Value:"12pm, after Holy Qurbana",Source:"Solo Song Guidelines 2020"},{Key:"GradeCutoffDate",Kind:"date",Label:"Date grades are counted from",Value:"2020-01-01",Source:"Group matrix"},{Key:"Venue",Kind:"address",Label:"Event venue",Value:{Name:"St. Gregorios Orthodox Church of Toronto",Address:"6890 Professional Court",City:"Mississauga, ON L4V 1X6",MapUrl:"",Directions:""},Source:"Solo Song Guidelines 2020"}],l=[{Claim:"Rules, judging components and group grades of the 2020 Solo Song Competition.",SourceType:"Primary - organiser's own circular",Source:"Solo Song Guidelines 2020",Url:"https://sgoctoronto.org/wp-content/uploads/2020/02/Solo-Song-Competition-Categories-and-Guidelines-2020.pdf"}],d={TemplateKey:e,Year:2020,Note:t,Page:o,ParticipantTypes:i,AgeGroups:n,Competitions:a,CompetitionAgeGroups:s,Variables:r,Evidence:l};export{n as AgeGroups,s as CompetitionAgeGroups,a as Competitions,l as Evidence,t as Note,o as Page,i as ParticipantTypes,e as TemplateKey,r as Variables,c as Year,d as default};
